      'วันเต็มกับฝูงช้างของทารังกิเร ใต้ต้นเบาบับที่ยืนต้นมานานกว่าพันปี',
      'เช้าวัฒนธรรมคาราตูระหว่างทารังกิเรและปล่องภูเขาไฟ — การพักจากเกมไดรฟ์อย่างแท้จริงและไม่เร่งรีบ ที่ทั้งเด็กและผู้ใหญ่มักจดจำได้นานที่สุด',
      'ปล่องภูเขาไฟโงโรงโกโรแบบเต็มรูปแบบ — สัตว์เกือบ 30,000 ตัวภายในแอ่งภูเขาไฟปิดแห่งเดียว พร้อมบิ๊กไฟว์ครบทุกชนิด',
