      "การได้เห็นสัตว์ป่ากับการอยู่ในตำแหน่งที่พร้อมสำหรับมันนั้นแตกต่างกัน — และความแตกต่างนี้คือแนวคิดหลักของกำหนดการนี้ทั้งหมด เจ็ดวันในสามระบบนิเวศ แต่ละแห่งถูกเลือกไม่ใช่เพียงเพราะสิ่งที่อาศัยอยู่ที่นั่น แต่เพราะสิ่งที่มันเปิดโอกาสให้ท่านทำได้ด้วยกล้องถ่ายรูปหรือความอยากรู้อยากเห็นอย่างแท้จริง ไม่ว่าจะเป็นฝูงช้างแห่งทารังกิเรที่เคลื่อนผ่านใต้ต้นเบาบับอายุนับพันปี การพบปะวัฒนธรรมมาไซและเมืองตลาดมโต วา มบู การลงสู่โลกปิดของปล่องภูเขาไฟโงโรงโกโรที่มีสัตว์เกือบ 30,000 ตัวอย่างเต็มรูปแบบ และสามวันบนทุ่งหญ้าสั้นแห่งนดูตูในช่วงฤดูคลอดลูก เมื่อลูกวิลเดอบีสต์มากถึง 8,000 ตัวถือกำเนิดในวันเดียว และนักล่าทุกตัวในระบบนิเวศต่างก็รู้ดี",
      "ทริปนี้ออกแบบมาสำหรับนักเดินทางสองกลุ่มที่มีความต้องการทับซ้อนกัน คือช่างภาพที่ต้องการไกด์ผู้อ่านแสงและพฤติกรรมสัตว์ได้ละเอียดพอ ๆ กับที่อ่านภูมิประเทศ และนักเดินทางสายผจญภัยที่อยากใช้เวลาแท้จริงในสถานที่น้อยแห่งมากกว่าจะเร่งรีบไล่ตามรายการอุทยาน มีให้เลือกสองระดับ ได้แก่ Wilderness Reserve และ Wilderness Sovereign ซึ่งเดินทางตามเส้นทาง 7 วันเดียวกันทุกประการ โดยระดับของแคมป์จะเปลี่ยนไปตามระดับที่เลือก",
