      "เริ่มต้นด้วยฝูงช้างแห่งอัมโบเซลีที่หากินอยู่บนทุ่งใต้เงาคิลิมันจาโร จากนั้นหนึ่งคืนและหนึ่งวันเต็มในมาไซมารา รวมถึงดินแดนข้ามแม่น้ำมารา ก่อนการข้ามพรมแดนทางบกที่อิซิบาเนียพาท่านข้ามจากเคนยาสู่เซเรนเกติของแทนซาเนียอย่างไร้รอยต่อ ซึ่งในทางนิเวศวิทยาแล้วเป็นผืนแผ่นดินต่อเนื่องเดียวกันแม้จะมีเส้นแบ่งทางการเมืองคั่นอยู่ก็ตาม สองวันเต็มในดินแดนเสือชีตาห์และสิงโตแห่งเซเรนเกติ นำไปสู่วันเต็มภายในปล่องภูเขาไฟโงโรงโกโรและจุดแวะที่ทะเลสาบมันยารา ที่ซึ่งสิงโตปีนต้นไม้เป็นพฤติกรรมที่ไม่พบที่ใดอีกในแอฟริกาตะวันออก มีให้เลือกทั้งระดับสบายหรือพรีเมียมตลอดทริป นี่คือไฮไลต์รวมที่สร้างขึ้นสำหรับนักเดินทาง และโดยเฉพาะช่างภาพ ที่ต้องการภูมิทัศน์อันเป็นเอกลักษณ์ของทั้งสองประเทศโดยไม่ต้องตัดทอนสิ่งใดออกไป",
