        "ซาฟารีนี้จับจังหวะตามฤดูนักล่าประจำถิ่นแทน เมื่อฝูงสัตว์อพยพเคลื่อนที่ต่อไปแล้ว แต่แมวหวงถิ่นที่เรียกนดูตูว่าบ้านยังคงอยู่ และฝูงชนที่ตามการอพยพก็ไปพร้อมกับมัน สามวันเต็มในที่เดียว ไกด์ที่อธิบายระบบนิเวศและบริบทควบคู่ไปกับการพบสัตว์ และการเยี่ยมชมชุมชนมาไซอย่างแท้จริง ถูกสร้างขึ้นเพื่อสร้างเนื้อหาที่แท้จริง ไม่ใช่แค่ภาพถ่าย",
